def zip_tuples(tuples):
    if not tuples or not tuples[0]:
        return []
    first, second = (tuples[0], tuples[1])
    len_first, len_second = (len(first), len(second))
    result = []
    for i in range(len_first):
        result.append((first[i], second[i % len_second]))
    return result


