def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if length == 1:
        if num < 9:
            return num + 1
        else:
            return 11

    def is_all_nines(s):
        return all((ch == '9' for ch in s))
    if is_all_nines(s):
        return int('1' + '0' * (length - 1) + '1')

    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]
    half_len = (length + 1) // 2
    left = s[:half_len]
    odd_length = length % 2 != 0
    palindrome = make_palindrome(left, odd_length)
    palindrome_num = int(palindrome)
    if palindrome_num > num:
        return palindrome_num
    left_int = int(left)
    left_int += 1
    left = str(left_int)
    if len(left) > half_len:
        return int('1' + '0' * (length - 1) + '1')
    palindrome = make_palindrome(left, odd_length)
    return int(palindrome)


