def find_solution(a, b, n):

    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - x // y * t)
    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'
    x0 *= n // g
    y0 *= n // g
    a_div = a // g
    b_div = b // g
    from math import ceil, floor
    k_min = -float('inf')
    k_max = float('inf')
    if b_div != 0:
        k_min = ceil(-x0 / b_div) if b_div > 0 else ceil(-x0 / b_div)
    if a_div != 0:
        k_max = floor(y0 / a_div) if a_div > 0 else floor(y0 / a_div)
    if k_min > k_max:
        return 'No solution'
    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div
    if x < 0 or y < 0:
        return 'No solution'
    return ('x = ', x, ', y = ', y)


