def get_total_number_of_sequences(m, n):
    if n == 0:
        return 0
    if n == 1:
        return m
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for x in range(1, m + 1):
        dp[1][x] = 1
    for i in range(2, n + 1):
        prefix_sums = [0] * (m + 1)
        for y in range(1, m + 1):
            prefix_sums[y] = prefix_sums[y - 1] + dp[i - 1][y]
        for x in range(1, m + 1):
            max_prev = x // 2
            if max_prev >= 1:
                dp[i][x] = prefix_sums[max_prev]
            else:
                dp[i][x] = 0
    return sum(dp[n][1:])


