            return b.list(args) + [sizes[0]] * (least - b.len(args))
        return args

    def call(*args, **kwargs):
        if not kwargs and b.len(args) > most:
            args = fit(args)
        elif not kwargs and b.len(args) < least:
            args = grow(args)
