def min_flip_to_make_string_alternate(s):

    def flips_for_pattern(start_char):
        flips = 0
        expected = start_char
        for ch in s:
            if ch != expected:
                flips += 1
            expected = '1' if expected == '0' else '0'
        return flips
    return min(flips_for_pattern('0'), flips_for_pattern('1'))


