def drop_empty(d):
    """
    Return a dictionary excluding items with "empty" values.

    "Empty" values are those that are falsey except for 0 and False,
    which should be kept.

    Examples:
    drop_empty({'a': 1, 'b': None, 'c': '', 'd': 0}) -> {'a': 1, 'd': 0}
    drop_empty({'x': False, 'y': [], 'z': 'hello'}) -> {'x': False, 'z': 'hello'}
    """

    def is_empty(value):
        if value in (0, False):
            return False
        return not bool(value)
    return {k: v for k, v in d.items() if not is_empty(v)}


