def find_Max(nums):
    if not nums:
        return None
    left, right = (0, len(nums) - 1)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    return nums[left - 1]


