def next_smallest_palindrome(num: int) -> int:
    if num < 0:
        return 0

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]
    if num < 9:
        return num + 1
    s = str(num)
    length = len(s)

    def make_palindrome(left: str, middle: str='') -> int:
        return int(left + middle + left[::-1])
    if length % 2 == 0:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]
    else:
        left = s[:length // 2]
        middle = s[length // 2]
        right = s[length // 2 + 1:]
    if middle:
        palindrome = make_palindrome(left, middle)
    else:
        palindrome = make_palindrome(left)
    if palindrome > num:
        return palindrome
    if middle:
        left_middle_num = int(left + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)
        if len(left_middle_str) > len(left) + 1:
            return int('1' + '0' * (length - 1) + '1')
        new_left = left_middle_str[:-1]
        new_middle = left_middle_str[-1]
        return make_palindrome(new_left, new_middle)
    else:
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            return int('1' + '0' * (length - 1) + '1')
        return make_palindrome(left_str)


