def get_total_number_of_sequences(N, K):
    """
    Counts the number of ordered sequences of length K where:
    - Each term is a positive integer up to N (1 <= term <= N)
    - Each term is at least double the previous one (a[i] >= 2 * a[i-1])

    Parameters:
    - N (int): the upper limit for sequence terms
    - K (int): length of the sequences

    Returns:
    - int: total count of such sequences
    """
    if K == 0:
        return 0
    dp_prev = [1] * (N + 1)
    for length in range(2, K + 1):
        dp_curr = [0] * (N + 1)
        prefix_sum = [0] * (N + 1)
        for x in range(1, N + 1):
            prefix_sum[x] = prefix_sum[x - 1] + dp_prev[x]
        for x in range(1, N + 1):
            max_prev = x // 2
            if max_prev >= 1:
                dp_curr[x] = prefix_sum[max_prev]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr
    return sum(dp_prev[1:])


