def remove_column(data, pos):
    if isinstance(data, (list, tuple)):
        if not data:
            return type(data)()
        if all((not isinstance(x, (list, tuple)) for x in data)):
            if 0 <= pos < len(data):
                new_seq = data[:pos] + data[pos + 1:]
            else:
                new_seq = data
            return type(data)(new_seq)
        else:
            return type(data)((remove_column(x, pos) for x in data))
    else:
        return data


