def reverse_Array_Upto_K(seq, k):
    if k < 0:
        reversed_prefix = seq[::-1]
        return list(reversed_prefix)
    else:
        reversed_prefix = seq[:k][::-1]
        suffix = seq[k:]
        return list(reversed_prefix) + list(suffix)


