def filter_data(data, min_height=0, min_weight=0):
    """
    Filters a dictionary mapping individual names to (height, weight) tuples,
    returning a dictionary containing only those individuals whose height and weight
    meet or exceed the specified minimum thresholds.

    Parameters:
    - data: dict[str, tuple[height, weight]]
    - min_height: minimum height threshold (inclusive)
    - min_weight: minimum weight threshold (inclusive)

    Returns:
    - dict[str, tuple[height, weight]] filtered by thresholds
    """
    return {name: (height, weight) for name, (height, weight) in data.items() if height >= min_height and weight >= min_weight}


