import re

def capital_words_spaces(text):
    """
    Adjust spacing in text before capitalized letters according to these rules:
    - Insert one space before each capital letter unless it is the very start of the string.
    - Remove multiple spaces before capitals (only one space).
    - Insert spaces between consecutive capitals (each capital letter is treated separately).
    - Leading and trailing spaces from the input should be stripped; internal spacing adjusted as above.

    The result:
    - No leading spaces.
    - Exactly one space before every capital letter except at start.
    - Consecutive capitals are split by spaces.
    - Multiple spaces anywhere else are reduced to single spaces.
    """
    text = text.strip()
    text = re.sub('\\s+', ' ', text)
    result_chars = []
    for i, ch in enumerate(text):
        if ch.isupper():
            if i == 0:
                result_chars.append(ch)
            else:
                prev = text[i - 1]
                if result_chars and result_chars[-1] != ' ':
                    result_chars.append(' ')
                result_chars.append(ch)
        else:
            result_chars.append(ch)
    result = ''.join(result_chars)
    result = re.sub('\\s+', ' ', result)
    return result


