def div_of_nums(seq):
    """
    Given a sequence of integers or floats, return a list of values from the input
    that are divisible by at least one other distinct nonzero value in the input.
    Skip zeros (do not consider zero as divisor or dividend).
    Division means "value % divisor == 0" for integers,
    and for floats, consider divisible if their division results in an integer without remainder.

    Parameters:
        seq (list or tuple): sequence of int or float numbers.

    Returns:
        list: values divisible by at least one different nonzero value in seq.
    """
    result = []
    values = list(seq)
    nonzero_values = [v for v in values if v != 0]
    for val in values:
        if val == 0:
            continue
        for div in nonzero_values:
            if div == val:
                continue
            try:
                quotient = val / div
            except ZeroDivisionError:
                continue
            if abs(quotient - round(quotient)) < 1e-12:
                result.append(val)
                break
    return result


