def substract_elements(groups, pairs):
    """
    Subtract elements pairwise by position from groups and pairs.

    Both `groups` and `pairs` are sequences of groups (tuples of tuples).
    The result is a tuple of tuples where each element is the difference
    of the corresponding elements in groups and pairs.

    If groups and pairs have different lengths, subtraction is done up to
    the shortest length. Similarly for inner tuples.

    Example:
    substract_elements(((1, 2), (3, 4)), ((1, 1), (2, 2))) -> ((0, 1), (1, 2))
    """
    result = []
    for g_group, p_group in zip(groups, pairs):
        result.append(tuple((g - p for g, p in zip(g_group, p_group))))
    return tuple(result)


