from collections import Counter

def lucky_num(seq):
    """
    Given a sequence of integers, return a list of unique integers appearing in input order,
    whose count in the sequence equals their value.
    """
    counts = Counter(seq)
    seen = set()
    result = []
    for num in seq:
        if num not in seen and counts[num] == num:
            result.append(num)
            seen.add(num)
    return result


