def next_smallest_palindrome(n):
    """
    Find the smallest palindrome strictly greater than n.
    """
    s = str(n)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return int('1' + '0' * (length - 1) + '1')

    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]
    odd_length = length % 2 != 0
    half_len = (length + 1) // 2
    left = s[:half_len]
    palindrome = make_palindrome(left, odd_length)
    if int(palindrome) > n:
        return int(palindrome)
    else:
        left_num = int(left) + 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            return int('1' + '0' * (length - 1) + '1')
        palindrome = make_palindrome(left_str, odd_length)
        return int(palindrome)


