def find_solution(a, b, n):
    """
    Finds non-negative integers x, y such that a*x + b*y = n,
    or returns None if no such solution exists.
    """
    if n < 0 or a <= 0 or b <= 0:
        return None
    max_x = n // a
    for x in range(max_x + 1):
        remaining = n - a * x
        if remaining < 0:
            break
        if remaining % b == 0:
            y = remaining // b
            if y >= 0:
                return (x, y)
    return None


