def sum_column(data, col=None):
    """
    Sum elements column-wise in a list of lists (or tuples) of numbers.

    If col is None, return a list of sums for all columns, treating missing elements as zero.
    If col is an integer, return the sum of that single column, treating missing elements as zero.

    Args:
        data (list or tuple of list or tuple): The input 2D sequence of numbers.
        col (int or None): Optional column index to sum.

    Returns:
        list or number: List of sums for all columns if col is None, else sum of the specified column.
    """
    if not data:
        if col is None:
            return []
        else:
            return 0
    max_len = max((len(row) for row in data))
    if col is not None:
        if col < 0 or col >= max_len:
            return 0
        total = 0
        for row in data:
            if col < len(row):
                total += row[col]
        return total
    sums = [0] * max_len
    for row in data:
        for i in range(len(row)):
            sums[i] += row[i]
    return sums


