def lucky_num(n):
    size = n * 10
    numbers = list(range(1, 2 * size, 2))
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n and idx >= len(numbers):
            break
    return numbers[:n]


