def compute_Last_Digit(A, B):
    if A > B:
        A, B = (B, A)
    if A == B:
        return 1
    if B - A >= 5:
        return 0
    product = 1
    start = int(A) + 1
    end = int(B)
    for x in range(start, end + 1):
        product *= x
    return product % 10


