def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if all((c == '9' for c in s)):
        return int('1' + '0' * (length - 1) + '1')
    digits = list(s)

    def mirror_left_to_right(d):
        half = length // 2
        if length % 2 == 0:
            for i in range(half):
                d[-(i + 1)] = d[i]
        else:
            for i in range(half):
                d[-(i + 1)] = d[i]

    def increment_middle(d):
        mid = length // 2
        left = mid - 1
        right = mid + 1 if length % 2 == 1 else mid
        if length % 2 == 1:
            if d[mid] != '9':
                d[mid] = str(int(d[mid]) + 1)
                return
            else:
                d[mid] = '0'
        while left >= 0:
            if d[left] != '9':
                d[left] = str(int(d[left]) + 1)
                d[right] = d[left]
                return
            else:
                d[left] = '0'
                d[right] = '0'
                left -= 1
                right += 1
        d.insert(0, '1')
        d.append('1')
    mirror_left_to_right(digits)
    candidate = int(''.join(digits))
    if candidate > num:
        return candidate
    increment_middle(digits)
    return int(''.join(digits))


