def find_solution(a, b, n):

    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - aa // bb * y1
            return (g, x, y)
    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None
    x = x0 * (n // g)
    y = y0 * (n // g)
    return ('x = ', x, ', y = ', y)


