def smallest_missing(arr, start, end):
    """
    Find the smallest missing non-negative integer in a sorted, strictly increasing array arr
    where arr[i] == i until the missing element.

    Args:
        arr (list or tuple): Sorted, strictly increasing array of integers.
        start (int): Start index of the subarray to search (inclusive).
        end (int): End index of the subarray to search (inclusive).

    Returns:
        int: The smallest missing non-negative integer.
    """
    if start > end:
        return start
    mid = (start + end) // 2
    if arr[mid] == mid:
        return smallest_missing(arr, mid + 1, end)
    else:
        return smallest_missing(arr, start, mid - 1)


