def permute_string(s):
    if len(s) <= 1:
        return [s]
    first, rest = (s[0], s[1:])
    rest_perms = permute_string(rest)
    result = []
    for perm in rest_perms:
        for i in range(len(perm), -1, -1):
            result.append(perm[:i] + first + perm[i:])
    return result


