def highest_Power_of_2(seq):
    if not seq:
        return 0
    max_val = max((x for x in seq if x > 0)) if any((x > 0 for x in seq)) else 0
    if max_val == 0:
        return 0
    power = 1
    while power <= max_val:
        power <<= 1
    return power >> 1


