def move_num(s):
    """
    Given a string s, return a new string with all non-digit characters first (in original order),
    followed by all digit characters (in original order).
    """
    non_digits = [ch for ch in s if not ch.isdigit()]
    digits = [ch for ch in s if ch.isdigit()]
    return ''.join(non_digits + digits)


