from collections import Counter
from typing import Sequence

def check_subset(a: Sequence, b: Sequence) -> bool:
    """
    Returns True if every element in b appears at least as many times in a; otherwise False.
    """
    count_a = Counter(a)
    count_b = Counter(b)
    for elem, cnt in count_b.items():
        if count_a[elem] < cnt:
            return False
    return True


