def capital_words_spaces(s: str) -> str:
    if not s:
        return s
    result = [s[0]]
    length = len(s)
    for i in range(1, length):
        c = s[i]
        if c.isupper():
            prev = s[i - 1]
            next_char = s[i + 1] if i + 1 < length else None
            if prev.isalnum():
                if prev.islower() or prev.isdigit():
                    result.append(' ')
                elif next_char is not None and next_char.islower():
                    result.append(' ')
            else:
                pass
        result.append(c)
    return ''.join(result)


