def lucky_num(n):
    if n <= 0:
        return []

    def sieve(nums):
        i = 1
        while i < len(nums):
            step = nums[i]
            if step > len(nums):
                break
            nums = [num for idx, num in enumerate(nums) if (idx + 1) % step != 0]
            i += 1
        return nums
    length = max(10, n * 3)
    while True:
        nums = list(range(1, 2 * length, 2))
        lucky = sieve(nums)
        if len(lucky) >= n:
            return lucky[:n]
        length *= 2


