def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return num + 2

    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]
    odd = length % 2 != 0
    mid = length // 2
    if odd:
        left = s[:mid + 1]
    else:
        left = s[:mid]
    palindrome = make_palindrome(left, odd)
    palindrome_num = int(palindrome)
    if palindrome_num > num:
        return palindrome_num
    if odd:
        left_num = int(left) + 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            return int(left_str + left_str[:-1][::-1])
        else:
            return int(make_palindrome(left_str, True))
    else:
        left_num = int(left) + 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            return int(left_str + left_str[::-1])
        else:
            return int(make_palindrome(left_str, False))


