def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return m
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for x in range(1, m + 1):
        dp[1][x] = 1
    for i in range(2, n + 1):
        prefix = [0] * (m + 1)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[i - 1][x]
        for x in range(1, m + 1):
            max_y = x // 2
            if max_y >= 1:
                dp[i][x] = prefix[max_y]
            else:
                dp[i][x] = 0
    return sum(dp[n][1:])


