def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    result = {}
    for student_id, measurements in data.items():
        if not isinstance(measurements, dict):
            continue
        if 'height' not in measurements or 'width' not in measurements:
            continue
        h = measurements['height']
        w = measurements['width']
        if not (isinstance(h, (int, float)) and isinstance(w, (int, float))):
            continue
        if min_height is not None and h < min_height:
            continue
        if max_height is not None and h > max_height:
            continue
        if min_width is not None and w < min_width:
            continue
        if max_width is not None and w > max_width:
            continue
        result[student_id] = (h, w)
    return result


