def lucky_num(n):
    if n <= 0:
        return []
    limit = max(10, 3 * n)
    while True:
        numbers = list(range(1, limit + 1))
        idx = 1
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
            idx += 1
        if len(numbers) >= n:
            return numbers[:n]
        limit *= 2


