def get_noOfways(n, tiles):
    """
    Counts the number of distinct ways to tile a 2 x n board using given tile lengths.
    Tiles are 2 x tile_length rectangles placed horizontally.

    Parameters:
    n (int): length of the board (width)
    tiles (list or tuple of ints): tile lengths (each tile is 2 x tile_length)

    Returns:
    int: number of ways to completely cover 2 x n board without gaps or overlaps.
    """
    if n == 0:
        return 1
    valid_tiles = [t for t in tiles if 1 <= t <= n]
    if not valid_tiles:
        return 0
    dp = [0] * (n + 1)
    dp[0] = 1
    for length in range(1, n + 1):
        ways = 0
        for t in valid_tiles:
            if t <= length:
                ways += dp[length - t]
        dp[length] = ways
    return dp[n]


