def zip_tuples(t1, t2):
    len1, len2 = (len(t1), len(t2))
    if len1 >= len2:
        longer, shorter = (t1, t2)
    else:
        longer, shorter = (t2, t1)
    shorter_len = len(shorter)
    result = []
    for i in range(max(len1, len2)):
        e1 = t1[i] if i < len1 else t1[i % len1]
        e2 = t2[i] if i < len2 else t2[i % len2]
        result.append((e1, e2))
    return result


