def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return int('1' + '0' * (length - 1) + '1')

    def mirror_left_to_right(s_list):
        """Mirror the left half onto the right half."""
        n = len(s_list)
        mid = n // 2
        left_end = mid if n % 2 == 0 else mid
        for i in range(left_end):
            s_list[-(i + 1)] = s_list[i]
    s_list = list(s)
    mirror_left_to_right(s_list)
    palindrome = int(''.join(s_list))
    if palindrome > num:
        return palindrome
    n = length
    mid = n // 2
    left = s_list[:mid]
    if n % 2 == 0:
        middle = []
        right = s_list[mid:]
    else:
        middle = [s_list[mid]]
        right = s_list[mid + 1:]
    if n % 2 == 0:
        left_num = int(''.join(left)) + 1
        left_str = str(left_num).rjust(len(left), '0')
        new_left = list(left_str)
        s_list[:mid] = new_left
        for i in range(mid):
            s_list[-(i + 1)] = s_list[i]
    else:
        left_middle_num = int(''.join(left + middle)) + 1
        left_middle_str = str(left_middle_num).rjust(len(left) + 1, '0')
        new_left = list(left_middle_str[:-1])
        new_middle = left_middle_str[-1]
        s_list[:mid] = new_left
        s_list[mid] = new_middle
        for i in range(mid):
            s_list[-(i + 1)] = s_list[i]
    return int(''.join(s_list))


