    if a == 0 and b == 0:
        if n == 0:
            return ('x = ', 0, ', y = ', 0)
        else:
            return 'No solution'
    if b == 0:
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return ('x = ', x, ', y = ', 0)
        return 'No solution'
    if a == 0:
        if b != 0 and n % b == 0:
            y = n // b
            return ('x = ', 0, ', y = ', y)
        return 'No solution'
    x = 0
    if a > 0:
        max_x = max(n // a, 0) + 1000
    else:
        max_x = 10 ** 6
    while x <= max_x:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return ('x = ', x, ', y = ', y)
        x += 1
    return 'No solution'


