def get_total_number_of_sequences(m, n):
    if n == 0 or m == 0:
        return 0
    if n == 1:
        return m
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        prefix = [0] * (m + 2)
        for i in range(1, m + 1):
            prefix[i] = prefix[i - 1] + dp[i]
        for x in range(1, m + 1):
            limit = x // 2
            if limit >= 1:
                new_dp[x] = prefix[limit]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1:])


