def smallest_missing(arr, left, right):
    """
    Find the smallest missing integer i in the subarray arr[left:right+1]
    such that arr[i] == i does NOT hold. The array is sorted but may contain
    any integers. The function assumes left and right are valid indices.

    Uses binary search to find the smallest index i in [left, right] for which arr[i] != i.
    If all arr[i] == i in the range, returns right + 1.

    Parameters:
    - arr: list or tuple of integers (sorted)
    - left: int, start index
    - right: int, end index

    Returns:
    - int: smallest missing integer i where arr[i] != i in the given range
    """
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == mid:
            left = mid + 1
        else:
            right = mid - 1
    return left


