def find_Max(seq, low, high):
    """
    Finds the largest item in an ordered, shifted sequence within seq[low:high+1].

    The sequence is assumed to be an ordered sequence rotated (shifted) some amount.
    The largest item is the one just before the rotation point, or the last item if no rotation point is found.

    Args:
        seq: a list or tuple of comparable items
        low: int, start index of the subrange (inclusive)
        high: int, end index of the subrange (inclusive)

    Returns:
        The largest item in seq[low:high+1]
    """
    if low == high:
        return seq[low]
    if seq[low] < seq[high]:
        return seq[high]
    while low < high:
        mid = (low + high) // 2
        if mid < high and seq[mid] > seq[mid + 1]:
            return seq[mid]
        if mid > low and seq[mid] < seq[mid - 1]:
            return seq[mid - 1]
        if seq[mid] >= seq[low]:
            low = mid + 1
        else:
            high = mid - 1
    return seq[low]


