def sum_Of_product(n: int) -> int:
    from math import comb
    total = 0
    for i in range(n + 1):
        c_i2 = comb(i, 2)
        if c_i2 == 0:
            continue
        for j in range(i + 1, n + 1):
            c_j3 = comb(j, 3)
            if c_j3 == 0:
                continue
            total += c_i2 * c_j3
    return total


