def even_Power_Sum(n: int) -> int:
    if n <= 0:
        return 0
    s = n * (n + 1)
    s2 = 2 * n + 1
    s3 = 3 * n * n + 3 * n - 1
    sum_i4 = s * s2 * s3 // 30
    return 16 * sum_i4


