def filter_data(data):
    """
    Filters a dictionary of people with their measurements to keep only those entries
    where all measurement values are numeric (int or float) and not None.

    Args:
        data (dict): A dictionary mapping people (keys) to dictionaries of measurements (values).

    Returns:
        dict: A filtered dictionary with only those people whose all measurement values are numeric.
    """
    filtered = {}
    for person, measurements in data.items():
        if isinstance(measurements, dict) and all((isinstance(v, (int, float)) and v is not None for v in measurements.values())):
            filtered[person] = measurements
    return filtered


