def check_Even_Parity(value):
    """
    Determine if the provided value has even parity.

    Even parity means the number of 1 bits in the binary representation is even.

    Args:
        value (int): The integer value to check parity for.

    Returns:
        bool: True if the number of 1 bits is even, False otherwise.
    """
    count_ones = bin(value).count('1')
    return count_ones % 2 == 0


