def substract_elements(a, b):
    """
    Subtract elements of two nested collections (lists or tuples) of numbers,
    returning a nested structure of the same shape as tuples of tuples.

    Rules:
    - Both inputs have the same nested structure.
    - If elements are numbers (int/float), subtract b from a.
    - If elements are sequences (list/tuple), recurse element-wise.
    - Always return tuples (not lists).
    """
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a - b
    return tuple((substract_elements(x, y) for x, y in zip(a, b)))


