def lucky_num(n):
    numbers = list(range(1, 2 * n * 10, 2))
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        numbers = [num for i, num in enumerate(numbers, 1) if i % step != 0]
        idx += 1
        if len(numbers) >= n:
            pass
    return numbers[:n]


