def get_noOfways(n, tiles=None):
    """
    Compute the number of ways to tile a 2 x n board using standard domino tiles.
    The tiles parameter is ignored since only standard domino tiles for 2 x n floor apply.

    Args:
        n (int): length of the 2 x n board.
        tiles (list or tuple, optional): ignored in this problem.

    Returns:
        int: number of distinct tilings of the 2 x n board with 2x1 dominoes.
    """
    if n < 0:
        return 0
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]


