def next_smallest_palindrome(num: int) -> int:
    """
    Return the smallest palindrome strictly greater than num.
    """
    s = str(num + 1)
    while True:
        if s == s[::-1]:
            return int(s)
        length = len(s)
        half = length // 2
        odd = length % 2 != 0
        left = s[:half]
        middle = s[half] if odd else ''
        palindrome = left + middle + left[::-1]
        if palindrome > s:
            return int(palindrome)
        elif odd:
            left_middle_num = int(left + middle) + 1
            left_middle_str = str(left_middle_num)
            if len(left_middle_str) > len(left + middle):
                s = '1' + '0' * (length - 1) + '1'
            else:
                left = left_middle_str[:-1]
                middle = left_middle_str[-1]
                palindrome = left + middle + left[::-1]
                s = palindrome
        else:
            left_num = int(left) + 1
            left_str = str(left_num)
            if len(left_str) > len(left):
                s = '1' + '0' * (length - 1) + '1'
            else:
                palindrome = left_str + left_str[::-1]
                s = palindrome


