def min_flip_to_make_string_alternate(s):
    pattern1 = '0'
    pattern2 = '1'
    flips1 = 0
    flips2 = 0
    for i, ch in enumerate(s):
        expected1 = pattern1 if i % 2 == 0 else pattern2
        expected2 = pattern2 if i % 2 == 0 else pattern1
        if ch != expected1:
            flips1 += 1
        if ch != expected2:
            flips2 += 1
    return min(flips1, flips2)


