def smallest_missing(arr):
    filtered = sorted(set((x for x in arr if isinstance(x, int) and x >= 0)))
    if not filtered or filtered[0] > 0:
        return 0
    left, right = (0, len(filtered))
    while left < right:
        mid = (left + right) // 2
        if filtered[mid] == mid:
            left = mid + 1
        else:
            right = mid
    return left


