def permute_string(s):
    if s == '':
        return ['']
    s = list(s)
    s.sort()
    used = [False] * len(s)
    result = []
    current = []

    def backtrack():
        if len(current) == len(s):
            result.append(''.join(current))
            return
        prev = None
        for i in range(len(s)):
            if used[i]:
                continue
            if prev == s[i]:
                continue
            used[i] = True
            current.append(s[i])
            backtrack()
            current.pop()
            used[i] = False
            prev = s[i]
    backtrack()
    return result


