def filter_data(students, height=None, width=None):
    """
    Filter students by minimum height and width thresholds inclusively.

    Parameters:
    - students: dict mapping student names to dicts with keys 'height' and 'width'
    - height: minimum height threshold (or None to ignore)
    - width: minimum width threshold (or None to ignore)

    Returns:
    - dict of students whose height >= height (if given) and width >= width (if given)
    """
    filtered = {}
    for name, measures in students.items():
        h = measures.get('height')
        w = measures.get('width')
        if height is not None and (h is None or h < height):
            continue
        if width is not None and (w is None or w < width):
            continue
        filtered[name] = measures
    return filtered


