def get_noOfways(n):
    """
    Returns the number of ways to tile a 2 x n board using 2 x 1 tiles.
    This is a classic tiling problem where the count follows a Fibonacci-like pattern.

    Parameters:
    n (int): The length of the board.

    Returns:
    int: Number of ways to tile the 2 x n board.
    """
    if n == 0:
        return 1
    if n == 1:
        return 1
    prev, curr = (1, 1)
    for _ in range(2, n + 1):
        prev, curr = (curr, curr + prev)
    return curr


