from typing import List, Union, Sequence

def below_zero(operations: Union[Sequence[int], str]) -> Union[bool, List[bool]]:
    if isinstance(operations, (list, tuple)):
        balance = 0
        for op in operations:
            balance += op
            if balance < 0:
                return True
        return False
    if isinstance(operations, str):
        balance = 0
        result = []
        for ch in operations:
            balance += int(ch)
            result.append(balance < 0)
        return result
    return False


