from typing import Sequence, Union
from statistics import mean

def mean_absolute_deviation(numbers: Sequence[float]) -> Union[float, str]:
    """ For a given list of input numbers, calculate Mean Absolute Deviation
    around the mean of this dataset. Input list can also contain strings. 
    Mean Absolute Deviation is the average absolute difference between each
    element and a centerpoint (mean in this case):
    MAD = average | x - x_mean |
    Returns a float value for MAD or 'Error' if any input is not a float.
    Calculation is performed without any loop structures.
    """
    if not all((isinstance(x, float) for x in numbers)):
        return 'Error'
    if not numbers:
        return 0.0
    m = mean(numbers)
    absolute_diffs = map(lambda x: abs(x - m), numbers)
    mad = sum(absolute_diffs) / len(numbers)
    return mad


