from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input: a string of multiple groups of nested parentheses separated by spaces.
    Output: a list of integers representing the maximum nesting depth for each group.

    No loops or recursion allowed.

    Example:
    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    from functools import reduce

    def max_depth(group: str) -> int:

        def reducer(acc, c):
            current_depth, max_d = acc
            if c == '(':
                current_depth += 1
                max_d = max(max_d, current_depth)
            elif c == ')':
                current_depth -= 1
            return (current_depth, max_d)
        _, max_d = reduce(reducer, group, (0, 0))
        return max_d
    return list(map(max_depth, paren_string.split()))


