from typing import List

def parse_music(music_string: str) -> List[int]:
    """Parses a string of space-separated notes ('o', 'o|', '.|') and returns a list of beats for each valid note.

    Runs in O(1) time by processing up to 11 notes explicitly without loops or recursion.

    Returns empty list if input is empty or has no valid notes.
    """
    notes = music_string.split()

    def beats(note: str) -> int:
        return 4 if note == 'o' else 2 if note == 'o|' else 1 if note == '.|' else 0
    b0 = beats(notes[0]) if len(notes) > 0 else 0
    b1 = beats(notes[1]) if len(notes) > 1 else 0
    b2 = beats(notes[2]) if len(notes) > 2 else 0
    b3 = beats(notes[3]) if len(notes) > 3 else 0
    b4 = beats(notes[4]) if len(notes) > 4 else 0
    b5 = beats(notes[5]) if len(notes) > 5 else 0
    b6 = beats(notes[6]) if len(notes) > 6 else 0
    b7 = beats(notes[7]) if len(notes) > 7 else 0
    b8 = beats(notes[8]) if len(notes) > 8 else 0
    b9 = beats(notes[9]) if len(notes) > 9 else 0
    b10 = beats(notes[10]) if len(notes) > 10 else 0
    beats_list = [b0, b1, b2, b3, b4, b5, b6, b7, b8, b9, b10]
    filtered = list(filter(lambda x: x != 0, beats_list))
    return filtered


