from typing import Any, List, Union, Sequence

def filter_integers(values: Union[str, Sequence[Any]]) -> List[int]:
    seq = list(values) if isinstance(values, str) else values

    def helper(s: Sequence[Any]) -> List[int]:
        if not s:
            return []
        head, *tail = s
        if type(head) is int:
            return [head] + helper(tail)
        else:
