def sort_even(l):
    """Return a list or tuple (same type as input) where elements at even indices
    are sorted ascending (stable) and elements at odd indices remain unchanged.

    Works for list or tuple of ints or strings or any comparable type.
    No loops or recursion, O(1) complexity (excluding sort).

    Examples:
    >>> sort_even([1, 2, 3])
    [1, 2, 3]
    >>> sort_even([5, 6, 3, 4])
    [3, 6, 5, 4]
    >>> sort_even(("c", "b", "a", "d"))
    ('a', 'b', 'c', 'd')
    >>> sort_even([1])
    [1]
    """
    evens = l[::2]
    sorted_evens = sorted(evens)
    result = list(l)
    result[::2] = sorted_evens
    return tuple(result) if isinstance(l, tuple) else result


