def monotonic(seq):

    def has_duplicates(s):
        if not s:
            return False

        def check(i):
            if i == len(s):
                return False
            if s[i] in s[:i]:
                return True
            return check(i + 1)
        return check(1)

    def strictly_increasing(s):
        if len(s) < 2:
            return True
        if s[0] >= s[1]:
            return False
        return strictly_increasing(s[1:])

    def strictly_decreasing(s):
        if len(s) < 2:
            return True
        if s[0] <= s[1]:
            return False
        return strictly_decreasing(s[1:])
    if isinstance(seq, (list, tuple)):
        if has_duplicates(seq):
            return False
        return strictly_increasing(seq) or strictly_decreasing(seq)
    elif isinstance(seq, str):
        if has_duplicates(seq):
            return False
        if strictly_increasing(seq) or strictly_decreasing(seq):
            return (True, seq)
        return False
    else:
        return False


