def search(lst):
    """
    You are given a non-empty list of positive integers or strings.
    - If the list contains integers:
      Return the greatest integer > 0 that appears at least as many times as its value.
      If no such integer exists, return -1 (int).
    - If the list contains strings:
      Return the lexicographically greatest string.
      If no strings exist, return -1 (int).

    No loops or recursion allowed.
    Complexity should be O(1) (interpreted as: use built-in functions and no explicit iteration).
    """
    first = lst[0]
    if isinstance(first, int):
        freq = Counter(lst)
        candidates = list(filter(lambda x: x > 0 and freq[x] >= x, freq.keys()))
        return max(candidates) if candidates else -1
    if isinstance(first, str):
        return max(lst) if lst else -1
    return -1


