def total_match(lst1, lst2):
    """
    Takes two lists (or tuples) of integers or strings.
    Returns the list with fewer total digits/characters (sum of digits for ints, sum of lengths for strings),
    preserving original order, and sorted ascending by numeric value if all integers.
    If both have equal totals, return the first list with the same ordering rules.
    If any strings present in a list, treat all elements by their length (strings length, ints digits count).
    No loops; O(1) time assumed since max 4 elements.
    """

    def digits_count(n):
        return len(str(abs(n)))

    def has_string(lst):
        return any((isinstance(x, str) for x in lst))

    def total_length(lst):
        l = len(lst)
        if l == 0:
            return 0
        elif l == 1:
            x0 = lst[0]
            return len(x0) if isinstance(x0, str) else digits_count(x0)
        elif l == 2:
            x0, x1 = lst
            return (len(x0) if isinstance(x0, str) else digits_count(x0)) + (len(x1) if isinstance(x1, str) else digits_count(x1))
        elif l == 3:
            x0, x1, x2 = lst
            return (len(x0) if isinstance(x0, str) else digits_count(x0)) + (len(x1) if isinstance(x1, str) else digits_count(x1)) + (len(x2) if isinstance(x2, str) else digits_count(x2))
        else:
            x0, x1, x2, x3 = lst[:4]
            return (len(x0) if isinstance(x0, str) else digits_count(x0)) + (len(x1) if isinstance(x1, str) else digits_count(x1)) + (len(x2) if isinstance(x2, str) else digits_count(x2)) + (len(x3) if isinstance(x3, str) else digits_count(x3))

    def all_int(lst):
        return all((isinstance(x, int) for x in lst))

    def sort_preserve_order(lst):
        if all_int(lst):
            return sorted(lst)
        else:
            return lst
    total1 = total_length(lst1)
    total2 = total_length(lst2)
    if total1 < total2:
        chosen = lst1
    elif total2 < total1:
        chosen = lst2
    else:
        chosen = lst1
    return sort_preserve_order(chosen)


