def move_one_ball(arr):
    if not arr:
        return True

    def is_sorted(seq):
        if len(seq) <= 1:
            return True
        return seq[0] <= seq[1] and is_sorted(seq[1:])

    def right_shift(seq):
        if not seq:
            return seq
        return (seq[-1],) + seq[:-1]
    seq = tuple(arr)

    def try_shifts(s, shifts_left):
        if is_sorted(s):
            return True
        if shifts_left == 0:
            return False
        return try_shifts(right_shift(s), shifts_left - 1)
    return try_shifts(seq, len(seq))


