def maximum(arr, k):
    """
    Return a sorted list of length k with the maximum k elements from arr.
    The output list is sorted in ascending order.
    The function should work for any comparable elements (ints, strings, etc.).
    No built-in sort functions are used.
    The function does not preserve original order of elements.
    """
    if k == 0:
        return []
    arr_copy = list(arr)
    largest = []
    for _ in range(k):
        max_elem = arr_copy[0]
        for elem in arr_copy[1:]:
            if elem > max_elem:
                max_elem = elem
        largest.append(max_elem)
        for i in range(len(arr_copy)):
            if arr_copy[i] == max_elem:
                del arr_copy[i]
                break
    for i in range(1, k):
        key = largest[i]
        j = i - 1
        while j >= 0 and largest[j] > key:
            largest[j + 1] = largest[j]
            j -= 1
        largest[j + 1] = key
    return largest


