def sum_squares(lst):
    """Given a list of numbers, return the sum of squared numbers after
    ceiling each element without using built-in ceil or round.
    Floats are processed normally.
    Return the sum as an integer (not a string).
    """

    def ceil_num(x):
        int_part = int(x)
        if x == int_part:
            return int_part
        if x > 0:
            return int_part + 1
        else:
            return int_part
    ceiled = map(ceil_num, lst)
    squared = map(lambda x: x * x, ceiled)
    return sum(squared)


