def sum_squares(lst):
    """
    Applies transformations to the first six entries of lst as follows:
    - Square entries at indices divisible by 3
    - Cube entries at indices divisible by 4 but not by 3
    - Leave others unchanged
    Sums these transformed first six entries and returns the sum as an integer.
    Runs in O(1) time without loops.
    """
    if not lst:
        return 0

    def get_val(i):
        return lst[i] if i < len(lst) else 0
    v0 = get_val(0) ** 2
    v1 = get_val(1)
    v2 = get_val(2)
    v3 = get_val(3) ** 2
    v4 = get_val(4) ** 3
    v5 = get_val(5)
    return v0 + v1 + v2 + v3 + v4 + v5


