def order_by_points(nums):
    """
    Sorts the given list of integers or strings representing integers in ascending order according to the sum of their digits.
    Preserves the original order for ties. Returns a list of the original values sorted accordingly.
    Returns an empty list if input is empty.
    Does not use loops or recursion.
    """

