def select_words(s, n):
    vowels = set('aeiouAEIOU')
    words = s.split()
    result = []
    for w in words:
        distinct_vowels = {ch.lower() for ch in w if ch in vowels}
        if n == 0:
            if distinct_vowels and all((ch.lower() in vowels for ch in w)):
                result.append(w)
        elif len(distinct_vowels) >= n:
            result.append(w)
    return result


