def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shifting the digits right by shift
    and return the result as a string.
    If shift > number of digits, return the digits reversed as a string.
    Otherwise, shift digits right by shift modulo digit count.

    >>> circular_shift(12, 1)
    '21'
    >>> circular_shift(12, 2)
    '12'
    >>> circular_shift(12345, 6)
    '54321'
    """
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    shift %= n
    return s[-shift:] + s[:-shift]


