def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list
    of length k with the maximum k numbers in arr.

    If k is 0, return an empty list.

    Args:
        arr (list or tuple of int): Input array of integers.
        k (int): Number of maximum elements to return.

    Returns:
        list of int: Sorted list of length k with the maximum k elements from arr.
    """
    if k == 0:
        return []
    max_k = sorted(arr, reverse=True)[:k]
    return sorted(max_k)


