from typing import Sequence

def mean_absolute_deviation(numbers: Sequence[float]) -> float:
    """ For a given sequence of input numbers, calculate Mean Absolute Deviation.
    The mean absolute deviation is the average of the absolute differences 
    between each number and the mean of the list.

    Returns 0.0 for an empty input sequence.

    >>> mean_absolute_deviation([1.0, 2.0, 3.0, 4.0])
    1.5
    >>> mean_absolute_deviation([5.0])
    0.0
    >>> mean_absolute_deviation([])
    0.0
    """
    if not numbers:
        return 0.0
    mean = sum(numbers) / len(numbers)
    return sum((abs(x - mean) for x in numbers)) / len(numbers)


