def prime_length(string):
    """
    Returns True if the length of the input string is a prime number greater than 1,
    otherwise returns False.

    Length 1 returns False (1 is neither prime nor composite).
    """
    n = len(string)
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True


