def order_by_points(nums):

    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            first_digit = -int(s[1])
            others = s[2:]
            others_sum = sum((int(d) for d in others))
            return first_digit + others_sum
        else:
            return sum((int(d) for d in s))
    return sorted(nums, key=digit_sum)


