def sort_even(seq: Union[List, Sequence]) -> List:
    """Return a list where the elements at even indices are sorted ascendingly,
    while elements at odd indices remain unchanged.
    """
    even_vals = sorted(seq[0::2])
    result = list(seq)
    for i, val in zip(range(0, len(seq), 2), even_vals):
        result[i] = val
    return result


