def monotonic(seq):
    if len(seq) <= 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(seq)):
        if seq[i] < seq[i - 1]:
            non_decreasing = False
        if seq[i] > seq[i - 1]:
            non_increasing = False
    return non_decreasing or non_increasing


