def smallest_change(arr):
    """
    Given a list or tuple of integers arr, returns the number of elements that need to be changed
    to make the array palindromic. Each change can modify one element to any other integer.

    This is computed by counting how many pairs of elements at symmetric positions differ,
    since each differing pair requires changing one element to match the other.
    """
    n = len(arr)
    count = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count


