def anti_shuffle(s):
    """
    Takes a string s, splits it by spaces preserving spaces, 
    and for each word (space-separated chunk), sorts all characters ascending by ASCII value,
    then joins back with spaces preserving the original number and positions of spaces.
    """
    import re
    tokens = re.split('(\\s+)', s)
    for i, token in enumerate(tokens):
        if not token.isspace():
            tokens[i] = ''.join(sorted(token))
    return ''.join(tokens)


