def count_upper(s):
    """
    Given a string s, count the number of uppercase vowels in even indices (0-based).

    Uppercase vowels are: 'A', 'E', 'I', 'O', 'U'

    Parameters:
    s (str or sequence of characters): input string or sequence

    Returns:
    int: count of uppercase vowels at even indices
    """
    vowels = {'A', 'E', 'I', 'O', 'U'}
    return sum((1 for i in range(0, len(s), 2) if s[i] in vowels))


