def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    min_val = min(arr)
    min_idx = arr.index(min_val)
    for i in range(n - 1):
        current = arr[(min_idx + i) % n]
        nxt = arr[(min_idx + i + 1) % n]
        if current > nxt:
            return False
    return True


