def select_words(s, n):
    vowels = set('aeiouAEIOU')

    def longest_increasing_subseq_length(seq):
        from bisect import bisect_left
        lis = []
        for x in seq:
            pos = bisect_left(lis, x)
            if pos == len(lis):
                lis.append(x)
            else:
                lis[pos] = x
        return len(lis)
    if not s:
        return []
    result = []
    for word in s.split():
        consonants = [ch.lower() for ch in word if ch.isalpha() and ch not in vowels]
        if not consonants:
            continue
        vals = [ord(c) - ord('a') + 1 for c in consonants]
        if longest_increasing_subseq_length(vals) >= n:
            result.append(word)
    return result


