from typing import Sequence

def below_zero(operations: Sequence[str]) -> bool:
    balance = 0
    for op in operations:
        parts = op.split()
        if len(parts) != 2:
            continue
        action, amount_str = parts
        try:
            amount = int(amount_str)
        except ValueError:
            continue
        if action == 'deposit':
            balance += amount
        elif action == 'withdraw':
            balance -= amount
        else:
            continue
        if balance < 0:
            return True
    return False


