def fizz_buzz(n: int) -> int:
    """
    Counts the occurrences of digit '7' in all numbers less than n
    that are divisible by 11 or 13.

    Args:
        n (int): The upper limit (exclusive).

    Returns:
        int: The count of digit '7' occurrences.
    """
    count = 0
    for x in range(1, n):
        if x % 11 == 0 or x % 13 == 0:
            count += str(x).count('7')
    return count


