from typing import Sequence, TypeVar
T = TypeVar('T')

def sort_even(seq: Sequence[T]) -> Sequence[T]:
    even_indices = [i for i in range(0, len(seq), 2)]
    even_elements = [seq[i] for i in even_indices]
    even_elements.sort()
    result = list(seq)
    for i, val in zip(even_indices, even_elements):
        result[i] = val
    return type(seq)(result)


