def triples_sum_to_zero(nums):
    nums = sorted(nums)
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = (i + 1, n - 1)
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False


