def monotonic(seq):
    if not seq:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(seq)):
        if seq[i] < seq[i - 1]:
            non_decreasing = False
        if seq[i] > seq[i - 1]:
            non_increasing = False
        if not non_decreasing and (not non_increasing):
            return False
    return True


