def parse_nested_parens(text):

    def max_depth(group):
        depth = 0
        max_d = 0
        for ch in group:
            if ch == '(':
                depth += 1
                if depth > max_d:
                    max_d = depth
            elif ch == ')':
                depth -= 1
        return max_d
    groups = text.split()
    return [max_depth(g) for g in groups]


