def sort_even(items):
    even_elements = [items[i] for i in range(0, len(items), 2)]
    even_elements.sort()
    if isinstance(items, tuple):
        result = list(items)
        is_tuple = True
    else:
        result = items[:]
        is_tuple = False
    even_idx = 0
    for i in range(0, len(items), 2):
        result[i] = even_elements[even_idx]
        even_idx += 1
    if is_tuple:
        return tuple(result)
    else:
        return result


