def monotonic(seq):
    """Return True if the sequence is entirely nondecreasing or entirely nonincreasing.

    An empty sequence or a sequence of length 1 is considered monotonic.
    """
    if len(seq) <= 1:
        return True
    nondecreasing = True
    nonincreasing = True
    for i in range(1, len(seq)):
        if seq[i] < seq[i - 1]:
            nondecreasing = False
        if seq[i] > seq[i - 1]:
            nonincreasing = False
        if not nondecreasing and (not nonincreasing):
            return False
    return True


