def smallest_change(items):
    """
    Given a sequence of values, returns the minimum number of entries that need to be altered
    to make the sequence a palindrome. Each alteration can replace one entry with any value.

    For example:
    smallest_change([1,2,3,5,4,7,9,6]) == 4
    smallest_change([1, 2, 3, 4, 3, 2, 2]) == 1
    smallest_change([1, 2, 3, 2, 1]) == 0
    smallest_change([1]) == 0
    """
    n = len(items)
    count = 0
    for i in range(n // 2):
        if items[i] != items[n - 1 - i]:
            count += 1
    return count


