import re

def anti_shuffle(text):
    """
    Process the input text preserving spaces exactly.
    For each token separated by spaces (tokens are sequences of non-space chars):
      - If the token is purely alphabetic, sort all letters ascending.
      - Else if the token starts and ends with non-alpha chars, and the inner substring is purely alphabetic,
        sort only the inner letters ascending, keep the surrounding non-alpha chars in place.
      - Otherwise, leave the token unchanged.
    Spaces are preserved as in the input.
    """

    def process_token(token):
        if token.isalpha():
            return ''.join(sorted(token))
        if len(token) > 2 and (not token[0].isalpha()) and (not token[-1].isalpha()):
            inner = token[1:-1]
            if inner.isalpha():
                return token[0] + ''.join(sorted(inner)) + token[-1]
        return token
    parts = re.split('(\\s+)', text)
    for i in range(0, len(parts), 2):
        parts[i] = process_token(parts[i])
    return ''.join(parts)


