def monotonic(l):
    """Return True if list elements are entirely nondecreasing or nonincreasing.
    Equal adjacent elements are permitted.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 3, 4])
    True
    >>> monotonic([5, 5, 5])
    True
    >>> monotonic([])
    True
    >>> monotonic([1])
    True
    """
    if not l:
        return True
    nondecreasing = True
    nonincreasing = True
    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            nondecreasing = False
        if l[i] > l[i - 1]:
            nonincreasing = False
    return nondecreasing or nonincreasing


