def prime_length(string):
    """Return True if the length of the string is prime, False otherwise.
    For this problem, length 1 is considered prime.
    """
    n = len(string)
    if n == 1:
        return True
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True


