def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    drops = 0
    drop_index = -1
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            drops += 1
            drop_index = i
    if drops == 0:
        return True
    if drops > 1:
        return False
    rotate = n - (drop_index + 1)
    rotated = arr[-rotate:] + arr[:-rotate]
    return all((rotated[i] <= rotated[i + 1] for i in range(n - 1)))


