def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k with the maximum k numbers in arr, counting duplicates separately.
    Return an empty list if k is 0.

    The returned list is sorted in ascending order.

    Examples:
    maximum([-3, -4, 5], 3) -> [-4, -3, 5]
    maximum([4, -4, 4], 2) -> [4, 4]
    maximum([-3, 2, 1, 2, -1, -2, 1], 1) -> [2]
    maximum([-1, -1, -1, -1], 2) -> [-1, -1]
    """
    if k == 0:
        return []
    sorted_desc = sorted(arr, reverse=True)
    top_k = sorted_desc[:k]
    return sorted(top_k)


