def monotonic(l):
    """Return True if list elements are monotonically increasing (non-decreasing).

    An empty list or single-element list is considered monotonically increasing.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
