def smallest_change(arr):
    """
    Given an array arr of integers, find the minimum number of elements that
    need to be changed to make the array palindromic.

    The minimum number of changes is the count of positions i where
    arr[i] != arr[len(arr)-1-i], because changing one of the two to match
    the other will fix that pair.

    Args:
        arr (list or tuple of int): The input array.

    Returns:
        int: The minimum number of elements to change to make arr palindromic.
    """
    n = len(arr)
    count = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count


