import re

def anti_shuffle(s):
    """
    Given a string s, return an "ordered version" of it:
    - The order of words and spaces is preserved.
    - Each "word" is processed individually.
    - For each word:
      * Trailing non-letter characters (punctuation) are moved to the front.
      * The first letter (if uppercase) is kept at the start.
      * The remaining letters are sorted alphabetically (case-insensitive).
      * Non-initial letters keep their case as in the original word.
      * If the first letter is not uppercase, all letters are sorted together.
    - Spaces are preserved exactly.

    Examples:
    anti_shuffle('Hi') -> 'Hi'
    anti_shuffle('hello') -> 'ehllo'
    anti_shuffle('Hello World!!!') -> 'Hello !!!Wdlor'
    anti_shuffle('special-characters! test') -> 'special-characters! estt'
    """

    def process_word(word):
        m = re.search('([A-Za-z]+)([^A-Za-z]*)$', word)
        if not m:
            return word
        letters_part = m.group(1)
        trailing_punct = m.group(2)
        if not letters_part:
            return trailing_punct + letters_part
        first_char = letters_part[0]
        rest_chars = letters_part[1:]
        if first_char.isupper():
            sorted_rest = ''.join(sorted(rest_chars, key=lambda c: c.lower()))
            reordered_letters = first_char + sorted_rest
        else:
            all_letters = letters_part
            reordered_letters = ''.join(sorted(all_letters, key=lambda c: c.lower()))
        return trailing_punct + reordered_letters
    parts = re.split('(\\s+)', s)
    result_parts = []
    for part in parts:
        if part.isspace() or part == '':
            result_parts.append(part)
        else:
            result_parts.append(process_word(part))
    return ''.join(result_parts)


