def select_words(s, n):
    vowels = set('aeiouAEIOU')
    result = []
    for word in s.split():
        consonant_count = 0
        for ch in word:
            if ch.isalpha() and ch not in vowels:
                consonant_count += 1
        if consonant_count == n:
            result.append(word)
    return result


