from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Given a string of groups of nested parentheses separated by spaces,
    return a list of integers where each integer is the maximum nesting depth
    of parentheses for the corresponding group.
    """
    result = []
    groups = paren_string.split()
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result


