from typing import List

def parse_music(music_string: str) -> List[int]:
    """
    Parses a space-separated string of note tokens and returns a list of integers representing
    the consecutive counts of identical tokens (notes).

    Each token is treated exactly as given (including letters, digits, etc.).
    Consecutive identical tokens are counted as one note lasting that many beats.
    """
    tokens = music_string.split()
    if not tokens:
        return []
    result = []
    current_note = tokens[0]
    count = 1
    for token in tokens[1:]:
        if token == current_note:
            count += 1
        else:
            result.append(count)
            current_note = token
            count = 1
    result.append(count)
    return result


