def monotonic(seq):
    """
    Returns True if the sequence is entirely non-increasing or non-decreasing, otherwise False.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1])
    True
    >>> monotonic([])
    True
    """
    if len(seq) <= 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(seq)):
        if seq[i] < seq[i - 1]:
            non_decreasing = False
        if seq[i] > seq[i - 1]:
            non_increasing = False
    return non_decreasing or non_increasing


