def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits
    and return the result as a string.

    Positive shift values rotate digits to the right.
    Negative shift values rotate digits to the left.
    """
    digits = str(x)
    n = len(digits)
    if n == 0:
        return digits
    shift = shift % n
    return digits[-shift:] + digits[:-shift]


