def anti_shuffle(s):
    """
    Takes a string s and returns a new string where each word's characters are sorted 
    independently by ascending ASCII order, preserving the original spaces as separators.
    """
    result = []
    word = []
    for ch in s:
        if ch == ' ':
            if word:
                result.append(''.join(sorted(word)))
                word = []
            result.append(ch)
        else:
            word.append(ch)
    if word:
        result.append(''.join(sorted(word)))
    return ''.join(result)


