from typing import List, Sequence

def mean_absolute_deviation(numbers: Sequence[float]) -> float:
    """ For a given set, calculate deviation.
    The deviation is the average absolute difference between each element and the mean.

    >>> mean_absolute_deviation([1.0, 2.0, 3.0, 4.0])
    1.0
    >>> mean_absolute_deviation([5.0])
    0.0
    """
    if not numbers:
        return 0.0
    mean = sum(numbers) / len(numbers)
    return sum((abs(x - mean) for x in numbers)) / len(numbers)


