def parse_nested_parens(paren_string):
    """
    Accepts a single string that may contain multiple parenthesis groups separated by spaces,
    and returns a list of deepest nesting levels corresponding to each group.

    Each group is a string containing zero or more '(' and ')' characters in any order.
    The function computes the deepest level of properly nested parentheses in each group,
    ignoring unmatched closing parentheses.
    """

    def max_depth(group):
        depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                if depth > 0:
                    depth -= 1
        return max_depth
    groups = paren_string.split()
    return [max_depth(group) for group in groups]


