def triples_sum_to_zero(l):
    """
    triples_sum_to_zero takes a list or tuple of integers.
    it returns True if there are three distinct elements in the list that sum to zero, else False.

    >>> triples_sum_to_zero([1, 3, 5, 0])
    False
    >>> triples_sum_to_zero([1, 3, -2, 1])
    True
    >>> triples_sum_to_zero([1, 2, 3, 7])
    False
    >>> triples_sum_to_zero([2, 4, -5, 3, 9, 7])
    True
    >>> triples_sum_to_zero([1])
    False
    """
    n = len(l)
    if n < 3:
        return False
    arr = list(l)
    arr.sort()
    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        target = -arr[i]
        left, right = (i + 1, n - 1)
        while left < right:
            s = arr[left] + arr[right]
            if s == target:
                return True
            elif s < target:
                left += 1
            else:
                right -= 1
    return False


