def smallest_change(arr):
    """
    Find the minimum number of elements that need to be changed to make the array palindromic.

    The minimal number of changes is the count of positions i where arr[i] != arr[-1 - i]
    for i in the first half of the array.
    """
    n = len(arr)
    changes = 0
    for i in range(n // 2):
        if arr[i] != arr[-1 - i]:
            changes += 1
    return changes


