def anti_shuffle(s):
    """
    Takes a string containing one or more words separated by spaces and returns a string where
    each word's characters are sorted in ascending ASCII order. Words are separated by single spaces.
    """
    words = s.split()
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)


