def count_upper(s):
    """
    Count the number of uppercase vowels in the input string s.
    Uppercase vowels are 'A', 'E', 'I', 'O', 'U'.

    Args:
        s (str): Input string.

    Returns:
        int: Number of uppercase vowels in s.

    Examples:
        count_upper('aBCdEf') -> 1  (E)
        count_upper('abcdefg') -> 0
        count_upper('dBBE') -> 1    (E)
        count_upper('AEIOU') -> 5
    """
    vowels = {'A', 'E', 'I', 'O', 'U'}
    return sum((1 for char in s if char in vowels))


