def max_fill(grid, capacity):
    import math
    total_bucket_uses = 0
    for well in grid:
        water_units = sum(well)
        if water_units > 0:
            uses = math.ceil(water_units / capacity)
            total_bucket_uses += uses
    return total_bucket_uses


