from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Given a string containing one or more groups of balanced parentheses separated by spaces,
    return a list of the maximum nesting depth for each group.

    Groups are separated only by literal spaces. Each non-empty chunk separated by spaces
    is treated as one group. Concatenated groups without spaces are treated as a single group.

    Example:
    parse_nested_parens('(()())((()))()((())()())') -> [1]  (one group)
    parse_nested_parens('(()()) ((())) () ((())()())') -> [2, 3, 1, 3]
    """
    result = []
    groups = [g for g in paren_string.split(' ') if g]
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result


