from typing import List

def parse_music(music_string: str) -> List[int]:
    """
    Parses a string of space-separated musical notes and returns a list of integers indicating the beats for each note.

    Legend (final interpretation based on user clarification):
    'o'  - whole note, lasts 4 beats
    'o|' - half note, lasts 1 beat
    '.|' - quarter note, lasts 2 beats

    >>> parse_music('o o| .| o| o| .| .| .| .| o o')
    [4, 1, 2, 1, 1, 2, 2, 2, 2, 4, 4]
    """
    beats_map = {'o': 4, 'o|': 1, '.|': 2}
    notes = music_string.split()
