def triples_sum_to_zero(seq):
    """
    Returns True if there exist three distinct elements in seq whose sum is zero,
    otherwise False.
    """
    nums = list(seq)
    nums.sort()
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = (i + 1, n - 1)
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False


