def monotonic(seq):
    """Return True if the sequence is monotonic (entirely nonincreasing or nondecreasing), False otherwise."""
    if not seq:
        return True
    increasing = decreasing = True
    for i in range(1, len(seq)):
        if seq[i] < seq[i - 1]:
            increasing = False
        if seq[i] > seq[i - 1]:
            decreasing = False
    return increasing or decreasing


