def anti_shuffle(s):
    """
    Takes a string and returns a string where each word’s characters (including trailing non-letters)
    are sorted in ascending ASCII order. Words and spaces keep their original order and spacing.
    """
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            result.append(' ')
            i += 1
        else:
            start = i
            while i < n and s[i] != ' ':
                i += 1
            word = s[start:i]
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word)
    return ''.join(result)


