def move_one_ball(arr):
    """
    Returns True if the array can be rotated (right shifted any number of times)
    to become sorted in non-decreasing (ascending) order, False otherwise.
    Returns True if the array is empty.
    """
    if not arr:
        return True
    n = len(arr)
    breaks = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            breaks += 1
            if breaks > 1:
                return False
    return True


