def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length ≤ k with the maximum k numbers in arr, including duplicates.
    If fewer than k elements are in arr, return all sorted ascending.

    Examples:
    maximum([5, 5, 5, 5], 3) -> [5, 5, 5]
    maximum([4, -4, 4], 2) -> [4, 4]
    maximum([-3, -4, 5], 3) -> [-3, 5, 5] (if arr had duplicates of 5)
    """
    if k == 0:
        return []
    arr_sorted_desc = sorted(arr, reverse=True)
    top_k = arr_sorted_desc[:k]
    return sorted(top_k)


